43	diff --git a/seed-b-backend.Api/Application/RatingService.cs b/seed-b-backend.Api/Application/RatingService.cs
44	new file mode 100644
45	index 0000000..dee2d07
46	--- /dev/null
47	+++ b/seed-b-backend.Api/Application/RatingService.cs
48	@@ -0,0 +1,67 @@
49	+using Microsoft.EntityFrameworkCore;
50	+using seed_b_backend.Api.Data;
51	+using seed_b_backend.Api.Domain;
52	+
53	+namespace seed_b_backend.Api.Application;
54	+
55	+public class RatingService(AppDbContext context)
56	+{
57	+    public async Task<RatingAggregate?> SubmitRatingAsync(
58	+        string productId,
59	+        string authorName,
60	+        int score,
61	+        CancellationToken ct = default)
62	+    {
63	+        var productExists = await context.Products.AnyAsync(p => p.Id == productId, ct);
64	+        if (!productExists)
65	+        {
66	+            return null;
67	+        }
68	+
69	+        var updatedRows = await context.Ratings
70	+            .Where(r => r.ProductId == productId && r.AuthorName == authorName)
71	+            .ExecuteUpdateAsync(s => s.SetProperty(r => r.Score, score), ct);
72	+
73	+        if (updatedRows == 0)
74	+        {
75	+            var newRating = new Rating { ProductId = productId, AuthorName = authorName, Score = score };
76	+            context.Ratings.Add(newRating);
77	+            try
78	+            {
79	+                await context.SaveChangesAsync(ct);
80	+            }
81	+            catch (DbUpdateException)
82	+            {
83	+                // Eine gleichzeitige Bewertungsabgabe für dasselbe (ProductId, AuthorName)
84	+                // hat ihre Zeile zwischen unserem ExecuteUpdateAsync (traf nichts) und
85	+                // diesem Add eingefügt — der DB-Unique-Constraint (AD-5) lehnt unseren
86	+                // Insert ab, statt still zu duplizieren. Fallback: Update, das jetzt
87	+                // garantiert genau diese Zeile trifft.
88	+                context.Entry(newRating).State = EntityState.Detached;
89	+                var raceFallbackRows = await context.Ratings
90	+                    .Where(r => r.ProductId == productId && r.AuthorName == authorName)
91	+                    .ExecuteUpdateAsync(s => s.SetProperty(r => r.Score, score), ct);
92	+
93	+                // Traf der Fallback keine Zeile, war die Ursache kein AD-5-Race (der hätte
94	+                // die Zeile ja gerade erst angelegt) — z. B. ein FK-Verstoß, weil das Produkt
95	+                // zwischen der Existenzprüfung oben und diesem SaveChangesAsync extern
96	+                // gelöscht wurde. In dem Fall NICHT still Erfolg vortäuschen.
97	+                if (raceFallbackRows == 0)
98	+                {
99	+                    throw;
100	+                }
101	+            }
102	+        }
103	+
104	+        var scores = await context.Ratings
105	+            .Where(r => r.ProductId == productId)
106	+            .Select(r => r.Score)
107	+            .ToListAsync(ct);
108	+
109	+        return new RatingAggregate
110	+        {
111	+            AverageRating = scores.Count > 0 ? scores.Average() : null,
112	+            RatingCount = scores.Count
113	+        };
114	+    }
115	+}
